{
  "summary": "Start by confirming your eligibility as an engaged couple, then gather the documents needed for the HFE application and submit the HFE to obtain the eligibility letter before the BTO launch.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "caveat",
      "text": "Whether an engaged couple can qualify as a first‑timer under the FT(PMC) category is not confirmed in the official policy, so you should verify this with HDB.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "First‑timer couples must be married, aged 40 or below, have never owned or sold a residential property, and must not have booked a BTO or SBF flat in the 5 years before applying.",
      "cited_fact_ids": ["PRI-FTPMC-001"]
    },
    {
      "claim_id": "c3",
      "kind": "policy_fact",
      "text": "Both applicants must be Singapore Citizens, and at least one core household member must be a Singapore Citizen or Permanent Resident.",
      "cited_fact_ids": ["HH-CIT-001"]
    },
    {
      "claim_id": "c4",
      "kind": "policy_fact",
      "text": "If neither applicant has taken any previous housing subsidy, the household is treated as a first‑timer family for priority purposes.",
      "cited_fact_ids": ["HH-SUBSIDY-001"]
    },
    {
      "claim_id": "c5",
      "kind": "preparation_step",
      "text": "Check with HDB (via the HDB website or hotline) whether your engaged status is acceptable for the FT(PMC) category.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c6",
      "kind": "preparation_step",
      "text": "Gather required documents for the HFE application: NRICs, CPF contribution statements, employment letters confirming full‑time status with CPF contributions, and recent payslips.",
      "cited_fact_ids": ["DOC-STATUS-001"]
    },
    {
      "claim_id": "c7",
      "kind": "preparation_step",
      "text": "Log in to the HDB Flat Portal, select the HFE application, and fill in each applicant’s employment status as “Employed with CPF contributions”.",
      "cited_fact_ids": ["DOC-STATUS-001"]
    },
    {
      "claim_id": "c8",
      "kind": "preparation_step",
      "text": "Submit the HFE application at least 3 months before the BTO launch you intend to apply for, as the HFE letter is typically valid for 6 months.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c9",
      "kind": "caveat",
      "text": "Exact timing and validity periods for the HFE letter may vary; confirm the latest details on the HDB website.",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [
    {
      "field": "relationship",
      "needed_for": ["application_requirements"],
      "follow_up_question": "Can you confirm whether you are willing to get married before the BTO application deadline?"
    }
  ],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "With your HFE letter, ensure the household details stay unchanged, verify you meet the age requirement for a Singapore Citizen buying with a non‑resident spouse, and avoid any private property interests before applying.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "For a new flat bought with a non‑resident spouse, the Singapore Citizen applicant must be at least 35 years old.",
      "cited_fact_ids": ["HH-NONRES-002"]
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "The household composition in the flat application must match the approved HFE letter; any change requires a new HFE letter.",
      "cited_fact_ids": ["APP-CHANGE-002"]
    },
    {
      "claim_id": "c3",
      "kind": "policy_fact",
      "text": "No applicant or occupier may own or hold an interest in any private residential property in Singapore or overseas, and a sold property requires a 30‑month waiting period before applying for an HFE letter.",
      "cited_fact_ids": ["HH-PROP-001"]
    },
    {
      "claim_id": "c4",
      "kind": "preparation_step",
      "text": "Log in to the HDB Flat Portal with Singpass and submit the flat application together with the current HFE letter before the letter expires.",
      "cited_fact_ids": ["HFE-APPLY-001"]
    },
    {
      "claim_id": "c5",
      "kind": "preparation_step",
      "text": "Check the expiry date of your HFE letter; if it will expire within 30 days and you need more time, apply for a fresh HFE letter.",
      "cited_fact_ids": ["HFE-RENEW-001"]
    },
    {
      "claim_id": "c6",
      "kind": "preparation_step",
      "text": "Ensure that both you (SC) and your SPR spouse have no prior HDB flat or subsidy, as first‑timer status is required for subsidy eligibility.",
      "cited_fact_ids": ["HH-CIT-001"]
    },
    {
      "claim_id": "c7",
      "kind": "caveat",
      "text": "Because Mei Xin is 31, she does not meet the 35‑year age requirement for a Singapore Citizen buying with a non‑resident spouse; she should verify whether any exemption applies or consider alternative options.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c8",
      "kind": "caveat",
      "text": "If any employment or income details change after the HFE letter is issued, a new HFE letter will be needed before applying.",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "Step 2 must be submitted within 30 calendar days of completing Step 1, and once Step 2 is submitted HDB may take up to one month to process the HFE letter.",
  "claims": [
    {
      "claim_id": "c1",
      "text": "Step 2 (the HFE letter application) must be completed no more than 30 calendar days after finishing Step 1.",
      "kind": "policy_fact",
      "cited_fact_ids": ["HFE-STEPS-001"]
    },
    {
      "claim_id": "c2",
      "text": "After a complete HFE letter application is submitted, HDB can take up to one month to process it.",
      "kind": "policy_fact",
      "cited_fact_ids": ["HFE-TIME-001"]
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "Yes, as an engaged couple of Singapore Citizens who are first‑timers you can apply for a BTO, provided you meet the age and other eligibility requirements and obtain an HFE letter.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "An engaged couple (fiancé and fiancée) counts as a core family nucleus and can apply together for a new HDB flat.",
      "cited_fact_ids": ["HH-COUPLE-001"]
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "First‑timer couples must be married or engaged, both Singapore Citizens, and must not have owned or sold any residential property or taken a housing subsidy before.",
      "cited_fact_ids": ["PRI-FTPMC-001", "HH-SUBSIDY-001"]
    },
    {
      "claim_id": "c3",
      "kind": "preparation_step",
      "text": "Apply for an HFE (Housing Flat Eligibility) letter before the BTO ballot; the letter confirms your eligibility and indicates the CPF grant and HDB loan amounts you may receive.",
      "cited_fact_ids": ["CTX-HFE-001"]
    },
    {
      "claim_id": "c4",
      "kind": "caveat",
      "text": "The FT(PMC) rules require married couples to be aged 40 or below; for engaged couples the age limit is not explicitly stated in the policy source, so you should verify the age requirement on the HDB website.",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [
    {
      "field": "applicant_1.age",
      "needed_for": ["application_requirements"],
      "follow_up_question": "What is Rachel's age?"
    },
    {
      "field": "applicant_2.age",
      "needed_for": ["application_requirements"],
      "follow_up_question": "What is Jun Hao's age?"
    }
  ],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "As a married Singapore Citizen couple with no prior flat ownership or subsidies, you fall under the standard couples scheme for new HDB flats.",
  "claims": [
    {
      "claim_id": "c1",
      "text": "Both applicants are Singapore Citizens, which satisfies the citizenship requirement for the couples scheme.",
      "kind": "policy_fact",
      "cited_fact_ids": ["HH-CIT-001"]
    },
    {
      "claim_id": "c2",
      "text": "Both spouses are over 21 years old, meeting the minimum age requirement for the couples scheme.",
      "kind": "policy_fact",
      "cited_fact_ids": ["HH-AGE-001"]
    },
    {
      "claim_id": "c3",
      "text": "Since neither of you has previously owned a flat or received a housing subsidy, you are classified as first‑timer buyers, which is a prerequisite for the couples scheme.",
      "kind": "policy_fact",
      "cited_fact_ids": ["HH-SUBSIDY-001"]
    },
    {
      "claim_id": "c4",
      "text": "As a married couple without children, you are treated as a first‑timer family under the FT(PMC) criteria for priority considerations.",
      "kind": "policy_fact",
      "cited_fact_ids": ["PRI-FTPMC-001", "HH-COUPLE-002"]
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "Yes, owning or having an interest in any private residential property disqualifies you from applying for a HFE letter, which you need to buy a BTO. You must not own, hold, or have recently sold such property (or wait 30 months after sale).",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "To buy a flat from HDB, no applicant or occupier in the HFE letter application may own, or hold an interest in, any private residential property in Singapore or overseas.",
      "cited_fact_ids": ["HH-PROP-001"]
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "Anyone who sold a private residential property must wait 30 months from the legal completion of the sale before applying for the HFE letter.",
      "cited_fact_ids": ["HH-PROP-001"]
    },
    {
      "claim_id": "c3",
      "kind": "caveat",
      "text": "If you have any other circumstances (e.g., property received as a gift or held in trust), the same restriction applies, but you should verify the details on the official HDB website.",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "Harith can only be listed as a core occupier, not as a joint applicant, because he is under 21 and the rules for engaged couples as joint applicants are unconfirmed.",
  "claims": [
    {
      "claim_id": "c1",
      "text": "An engaged partner who is under 21 may appear in the HFE application only as a core occupier, not as an applicant.",
      "kind": "policy_fact",
      "cited_fact_ids": ["HH-AGE-002"]
    },
    {
      "claim_id": "c2",
      "text": "Whether an engaged couple can qualify as joint applicants for a first‑timer BTO flat is not stated in the available policy sources, so the eligibility is unconfirmed.",
      "kind": "caveat",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c3",
      "text": "Both Tan Li and Harith must each be Singapore Citizens to be eligible as applicants under the couples scheme.",
      "kind": "policy_fact",
      "cited_fact_ids": ["HH-CIT-001"]
    },
    {
      "claim_id": "c4",
      "text": "Apply for the HFE letter online via the HDB Flat Portal with Singpass; the application is free.",
      "kind": "preparation_step",
      "cited_fact_ids": ["HFE-APPLY-001"]
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "Yes, Harith can be a joint applicant with you, provided both of you meet the age and citizenship requirements and have no prior flat or subsidy history.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "Under the couples scheme, an applicant must be 21 or older to buy a new HDB flat.",
      "cited_fact_ids": ["HH-AGE-001"]
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "For a new flat under the couples scheme, the applicant must be a Singapore Citizen, and the household must include at least one more person who is a Singapore Citizen or Singapore Permanent Resident.",
      "cited_fact_ids": ["HH-CIT-001"]
    },
    {
      "claim_id": "c3",
      "kind": "preparation_step",
      "text": "Both you and Harith should log in to the HDB Flat Portal with Singpass and apply for the HFE letter online.",
      "cited_fact_ids": ["HFE-APPLY-001"]
    },
    {
      "claim_id": "c4",
      "kind": "caveat",
      "text": "If either of you has previously owned or sold a private residential property, you must wait 30 months from the sale completion before applying for the HFE letter.",
      "cited_fact_ids": ["HH-PROP-001"]
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "Because your Step 1 and Step 2 fall in different calendar months, you must update the employment and income details before submitting Step 2. No other redo is needed if no other details have changed.",
  "claims": [
    {
      "claim_id": "c1",
      "text": "Step 1 and Step 2 must be completed within 30 calendar days.",
      "kind": "policy_fact",
      "cited_fact_ids": ["HFE-STEPS-001"]
    },
    {
      "claim_id": "c2",
      "text": "If Step 1 and Step 2 fall in different calendar months, the employment and income details of everyone in the application must be updated.",
      "kind": "policy_fact",
      "cited_fact_ids": ["HFE-STEPS-001"]
    },
    {
      "claim_id": "c3",
      "text": "Since your Step 1 was on 25 Oct 2026 and Step 2 is planned for 15 Nov 2026, they are in different months, so you need to update employment and income details before submitting Step 2.",
      "kind": "preparation_step",
      "cited_fact_ids": ["c2"]
    },
    {
      "claim_id": "c4",
      "text": "If any other personal details (e.g., marital status, citizenship, private property ownership) have changed since Step 1, you must cancel the pending HFE letter and redo both steps.",
      "kind": "caveat",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [
    {
      "field": "applicant_1.employment",
      "needed_for": ["updating_employment_income_details"],
      "follow_up_question": "What is Lim's current employment status and monthly income?"
    },
    {
      "field": "applicant_2.employment",
      "needed_for": ["updating_employment_income_details"],
      "follow_up_question": "What is Sara's current employment status and monthly income?"
    }
  ],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

